package com.phonecando.lre.cli.host

import org.junit.jupiter.api.Test
import java.io.File
import kotlin.test.assertEquals

class HostEnvsTest {
    @Test
    fun `nameservers only, in order, comments and options skipped`() {
        val text = """
            # Generated by systemd-resolved
            nameserver 127.0.0.53
            options edns0 trust-ad
            search example.internal
            nameserver   fe80::1%eth0   # link-local
            ;nameserver 9.9.9.9
            nameserver
        """.trimIndent()
        assertEquals(listOf("127.0.0.53", "fe80::1%eth0"), ResolvConf.nameservers(text))
        assertEquals(emptyList(), ResolvConf.nameservers(""))
    }

    @Test
    fun `by default the image dir's parent is the data dir`() {
        val env = HostEnvs.of(File("/w/lib"), File("/w/images/c1"), emptyList(), "nameserver 10.0.0.2\n", "/usr/bin:/bin")
        assertEquals("/w/lib", env.libDir)
        assertEquals(listOf("/w/images"), env.dataDirSpellings)
        assertEquals(listOf("10.0.0.2"), env.dnsServers)
        assertEquals("/usr/bin:/bin", env.hostPath)
    }

    @Test
    fun `given spellings win, and no resolv conf or PATH means empty`() {
        val env = HostEnvs.of(File("/l"), File("/w/i"), listOf("/data/user/0/p", "/data/data/p"), null, null)
        assertEquals(listOf("/data/user/0/p", "/data/data/p"), env.dataDirSpellings)
        assertEquals(emptyList(), env.dnsServers)
        assertEquals("", env.hostPath)
    }

    @Test
    fun `data dirs are made absolute and normalized, never resolved`() {
        val cwd = File("").absoluteFile
        assertEquals(listOf("/a/c", File(cwd, "rel").path), HostPaths.dataDirs(listOf("/a/b/../c/", "rel")))
    }
}
